from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("expressions", "3. Выражения и расчёты", "Деление, остатки, преобразования и контрольная по запасам.", [
        lesson("priority", "Порядок вычислений", "Переведите формулу на язык выражений.",
            "Умножение * и деление / имеют более высокий приоритет, чем + и -. Скобки меняют группировку: (a + b) * c сначала складывает a и b. Операции одного уровня + и - группируются слева направо: a - b - c означает (a - b) - c.\n\nУнарный минус меняет знак значения: -x. Для читаемости используйте именованные промежуточные результаты. Не рассчитывайте на запись 2(a+b): в C++ умножение записывают явно как 2 * (a + b).\n\nОперации ++ и -- изменяют переменную на 1. Префиксная форма ++i в качестве результата даёт новое значение переменной; постфиксная форма i++ даёт прежнее значение. Не пишите выражения с несколькими изменениями одной переменной в одной инструкции: порядок их эффектов не определён, и результат зависел бы от реализации.\n\nУсловная операция ?: выбирает между двумя значениями: условие ? значение_да : значение_нет. Это компактная развилка для выбора значения, а не инструкций; обе альтернативы вычисляются по одному и тому же типу. В задачах ниже условия простые, а изменения переменных — по одному в инструкции.\n\nВ задачах этого урока все целочисленные промежуточные результаты находятся в диапазоне −30000…30000. Это исключает переполнение даже на реализации с минимально допустимым диапазоном int.",
            program('int width = 4, height = 3;\nstd::cout << 2 * (width + height);'),
            "Приоритет говорит, как сгруппировано выражение, но не задаёт общий порядок вычисления его частей с побочными эффектами. Сейчас части — простые чтения переменных. Позже не пишите выражения вроде i++ + i++: правила последовательности — отдельная тема, а не следствие таблицы приоритетов.",
            "Сначала формула, затем явные *, скобки и проверка промежуточных значений.", [
                code("frame", "Рамка дисплея", 'Ввод: целые ширина w и высота h от 1 до 100. Выведите периметр прямоугольника.', 'int w = 0, h = 0;\nstd::cin >> w >> h;\nstd::cout << 2 * (w + h);', [("4 3", "14"), ("1 1", "4"), ("100 100", "400"), ("2 99", "202"), ("50 1", "102")], ["У прямоугольника две ширины и две высоты.", "Умножьте сумму w + h на 2."], "Без скобок 2*w+h удвоило бы только ширину."),
                output("group", "Без скобок и со скобками", 'std::cout << 2 + 3 * 4 << " " << (2 + 3) * 4;', "14 20", ["Умножение сильнее сложения.", "В правой части сначала выполняется сложение в скобках."], "Первый результат — 2+12, второй — 5*4."),
                code("robot", "Путь по двум коридорам", 'Ввод: длины коридоров a и b (0…100), число обходов n (0…100). Каждый обход проходит оба коридора. Выведите общую длину пути.', 'int a = 0, b = 0, n = 0;\nstd::cin >> a >> b >> n;\nstd::cout << (a + b) * n;', [("8 3 4", "44"), ("1 2 0", "0"), ("0 0 100", "0"), ("100 100 50", "10000"), ("0 7 3", "21")], ["Один обход имеет длину суммы двух коридоров.", "Группируйте a + b перед умножением на n."], "Число обходов умножает весь маршрут, а не только второй коридор."),
                choice("multiply", "Пропавшее умножение", 'Как записать математическую формулу 3(a + b) в C++?', ["3(a + b)", "3 * (a + b)", "3a + b"], 1, ["Неявного умножения рядом со скобками нет.", "Нужен знак * между 3 и скобкой."], "Явное умножение необходимо даже там, где математическая запись его опускает."),
                code("bill", "Счёт мастерской", 'Ввод: число деталей n (0…100), цена материала m и работы w на одну деталь (0…100), скидка d (0…100), d ≤ n*(m+w). Выведите итог n*(m+w)-d.', 'int n = 0, m = 0, w = 0, d = 0;\nstd::cin >> n >> m >> w >> d;\nint total = n * (m + w);\nstd::cout << total - d;', [("3 8 5 4", "35"), ("0 0 0 0", "0"), ("10 2 3 5", "45"), ("0 50 50 0", "0"), ("100 100 100 100", "19900")], ["Материал и работа относятся к каждой детали.", "Скидка вычитается один раз после умножения."], "Единицы измерения помогают понять скобки: цена за деталь умножается на количество.", difficulty=2),
                output("increments", "Префикс и постфикс", 'int i = 5;\nint a = i++;\nint b = ++i;\nstd::cout << a << " " << b << " " << i;', "5 7 7", ["a получает прежнее значение i.", "После i++ переменная стала 6, ++i дал b новое значение 7."], "Постфиксная форма отдаёт старое значение, префиксная — новое; каждая инструкция здесь содержит ровно одно изменение."),
                choice("postfix", "Что отдаёт i++?", 'Для int i = 3; какой результат даёт выражение i++?', ["4 — новое значение переменной", "3 — прежнее значение переменной", "Такая запись всегда ошибка компиляции"], 1, ["Переменная станет 4, но выражение уже посчиталось.", "Сравните с ++i, который отдаёт новое значение."], "Различие форм — один из частых устных вопросов; опирайтесь на значение выражения, а не на догадку о моменте изменения."),
                code("absvalue", "Модуль через тернарный оператор", 'Ввод: целое n от −100 до 100. Выведите модуль n через условную операцию ?:. Без std::abs.', 'int n = 0;\nstd::cin >> n;\nstd::cout << (n < 0 ? -n : n);', [("-7", "7"), ("0", "0"), ("42", "42"), ("-100", "100"), ("99", "99"), ("-1", "1")], ["Условие проверяет знак один раз.", "Отрицательному значению соответствует -n."], "Тернарная операция выбирает значение прямо в выражении вывода.", difficulty=2)
            ], ["приоритет", "скобки", "формулы", "инкремент", "тернарный оператор"]),
        lesson("division", "Деление и остаток", "Разделите груз на полные упаковки и остаток.",
            "Когда оба операнда целые, / выполняет целочисленное деление: 17 / 5 даёт 3. Остаток % дополняет это деление: 17 % 5 даёт 2. Для неотрицательного a и положительного b: a = (a / b) * b + a % b, остаток находится от 0 до b-1.\n\nС отрицательными целыми частное отбрасывается к нулю: -17 / 5 равно -3, а -17 % 5 равно -2. Это не округление вниз. В наших практических задачах на упаковку числа неотрицательные, поэтому бытовое понимание остатка подходит. Делить на ноль нельзя ни через /, ни через %. При вводе делителя условие гарантирует положительное число.",
            program('int cargo = 17, capacity = 5;\nstd::cout << cargo / capacity << " " << cargo % capacity;'),
            "Деление целого на ноль — неопределённое поведение. Нельзя обещать, что оно обязательно вызовет красивое сообщение или исключение. У знаковых целых также опасен случай наименьшего значения, делённого на −1, когда результат не представим. Такие входы исключены из задач.",
            "Целое частное отвечает «сколько полных групп», остаток — «сколько осталось». Всегда проверяйте область допустимых делителей.", [
                code("crates", "Упаковщик проб", 'Ввод: n проб (0…10000), вместимость k (1…100). Выведите число полных коробок и оставшихся проб через пробел.', 'int n = 0, k = 0;\nstd::cin >> n >> k;\nstd::cout << n / k << " " << n % k;', [("23 6", "3 5"), ("0 4", "0 0"), ("20 5", "4 0"), ("10000 100", "100 0"), ("1 100", "0 1"), ("9999 7", "1428 3")], ["Одна операция даёт полные коробки, другая — остаток.", "Используйте n / k и n % k."], "Остаток меньше вместимости: если он не меньше k, можно упаковать ещё коробку."),
                output("negative", "Отрицательное деление", 'std::cout << -17 / 5 << " " << -17 % 5;', "-3 -2", ["Частное целочисленного деления отбрасывается к нулю.", "Проверьте тождество: -3*5 + (-2) = -17."], "В C++17/20 это определённое поведение, а не особенность компилятора."),
                code("clock", "Минуты экспедиции", 'Ввод: длительность t в минутах (0…10000). Выведите полные часы и оставшиеся минуты через пробел.', 'int t = 0;\nstd::cin >> t;\nstd::cout << t / 60 << " " << t % 60;', [("135", "2 15"), ("59", "0 59"), ("60", "1 0"), ("0", "0 0"), ("10000", "166 40"), ("1439", "23 59")], ["Один час — группа из 60 минут.", "Часы получаются делением, минуты — остатком от деления на 60."], "Формат не требует ведущих нулей и не ограничивает число часов сутками."),
                choice("zero", "Опасный делитель", 'Что гарантирует стандарт при целочисленном делении на ноль?', ["Результат всегда 0", "Всегда выбрасывается исключение C++", "Поведение не определено; полагаться на результат нельзя"], 2, ["Не путайте сообщение конкретной системы с гарантией языка.", "Это один из примеров undefined behavior."], "Компилятор и среда не обязаны диагностировать такое выполнение одинаково."),
                code("digits", "Цифры кода доступа", 'Ввод: трёхзначное положительное число n (100…999). Выведите его сотни, десятки и единицы через пробел.', 'int n = 0;\nstd::cin >> n;\nstd::cout << n / 100 << " " << n / 10 % 10 << " " << n % 10;', [("407", "4 0 7"), ("999", "9 9 9"), ("100", "1 0 0"), ("123", "1 2 3"), ("505", "5 0 5"), ("990", "9 9 0")], ["Остаток от деления на 10 — последняя цифра.", "Для десятков сначала отбросьте единицы через /10, затем возьмите %10."], "Сотни — целая часть n/100; промежуточный ноль в числе 407 обязательно выводится.", difficulty=2)
            ], ["деление", "остаток", "цифры"]),
        lesson("conversion", "Преобразования и границы", "Не потеряйте дробь до сохранения в double.",
            "Тип результата операции определяется операндами, а не переменной назначения. double x = 5 / 2; сохраняет 2.0: целочисленное деление уже произошло. Запись 5.0 / 2 или static_cast<double>(a) / b выполняет вещественное деление. static_cast<double>(a) явно преобразует значение a.\n\nПреобразование double в int отбрасывает дробную часть в сторону нуля, но допустимо только когда получаемое значение представимо. Скобки и приведение должны стоять до операции, которая теряет нужную информацию. Не выводите правило «double всегда точнее всего»: у типов разные назначения и ограничения. Для малых целых в наших задачах преобразование в double точно.",
            program('int a = 5, b = 2;\ndouble ratio = static_cast<double>(a) / b;\nstd::cout << std::fixed << std::setprecision(2) << ratio;', "iostream iomanip"),
            "Знаковое целочисленное переполнение — неопределённое поведение. Нельзя безопасно «сначала переполнить int, потом сохранить в более широкий тип». Если нужен более широкий результат, расширяйте операнд до операции. Здесь используем int только в пределах ограничений, а большие величины вводим как long long в будущих задачах.",
            "Сначала определите тип операции, затем тип места хранения. Потерянная до присваивания дробь не восстановится.", [
                code("ratio", "Доля заполнения", 'Ввод: занятые места used (0…100), вместимость capacity (1…100), used ≤ capacity. Выведите долю used/capacity с тремя знаками после точки.', 'int used = 0, capacity = 0;\nstd::cin >> used >> capacity;\ndouble ratio = static_cast<double>(used) / capacity;\nstd::cout << std::fixed << std::setprecision(3) << ratio;', [("1 4", "0.250"), ("0 7", "0.000"), ("9 9", "1.000"), ("1 3", "0.333"), ("2 3", "0.667"), ("1 100", "0.010")], ["Нельзя делить два int, если нужна дробь.", "Приведите used к double до деления."], "Приведение результата used/capacity после целочисленного деления уже не вернуло бы дробь.", headers="iostream iomanip"),
                output("lost", "Куда исчезла половина?", 'double x = 5 / 2;\ndouble y = 5.0 / 2;\nstd::cout << x << " " << y;', "2 2.5", ["Посмотрите на типы операндов каждой операции.", "В первом случае оба операнда целые."], "Назначение double не меняет уже выполненную операцию 5/2."),
                code("average", "Средняя загрузка", 'Ввод: три целых измерения a,b,c от 0 до 100. Выведите среднее арифметическое с двумя знаками после точки.', 'int a = 0, b = 0, c = 0;\nstd::cin >> a >> b >> c;\ndouble average = (a + b + c) / 3.0;\nstd::cout << std::fixed << std::setprecision(2) << average;', [("1 2 5", "2.67"), ("0 0 0", "0.00"), ("100 100 100", "100.00"), ("0 1 2", "1.00"), ("50 50 51", "50.33")], ["Сумма мала и помещается в int.", "Делите на 3.0, чтобы получить double."], "Вещественный делитель переводит операцию в вещественную арифметику.", headers="iostream iomanip"),
                choice("overflow", "Позднее расширение", 'Почему сохранение переполнившегося произведения int в double не исправляет проблему?', ["Переполнение уже произошло до сохранения", "double вообще не хранит числа", "Компилятор всегда автоматически расширяет произведение"], 0, ["Тип переменной назначения не определяет тип умножения.", "Нужный тип выбирают до выполнения операции."], "Для знаковых целых переполнение уже означает undefined behavior; последующее присваивание не является восстановлением."),
                code("truncate", "Отбросьте дробную часть", 'Ввод: double x от −100 до 100. Выведите целую часть в сторону нуля через явный static_cast<int>.', 'double x = 0;\nstd::cin >> x;\nstd::cout << static_cast<int>(x);', [("-7.9", "-7"), ("8.2", "8"), ("0.9", "0"), ("-0.5", "0"), ("99.99", "99"), ("-99.99", "-99")], ["Это не округление до ближайшего и не вниз.", "Используйте static_cast<int>(x) при выводе."], "Для отрицательного числа отбрасывание дроби движется к нулю: −7.9 становится −7.", difficulty=2)
            ], ["преобразования", "диапазон", "double"]),
        lesson("bits", "Биты и маски", "Работайте с отдельными битами числа.",
            "Целое число хранится как последовательность двоичных разрядов. Битовые операции работают со всеми разрядами сразу: & даёт единицу только там, где единицы у обоих операндов; | — если единица есть хотя бы у одного; ^ — там, где операнды различаются.\n\nСдвиг n >> k соответствует делению на 2^k только для неотрицательных чисел. Для unsigned сдвиг влево — умножение по модулю 2^N, а сдвиг вправо заполняет старшие разряды нулями. Сдвиг влево отрицательного знакового значения в C++17 не определён, поэтому в битовых задачах курса вход читается в unsigned.\n\nМаска 1u << k выделяет один бит: проверить бит номер k можно выражением (n >> k) & 1u, установить — n | (1u << k), сбросить — n & ~(1u << k). Это чтение и запись флагов состояния, а не способ ускорить арифметику.",
            program('unsigned flags = 0b0110;\nstd::cout << ((flags >> 1) & 1u) << " " << (flags | (1u << 4));', "iostream"),
            "Сдвиги ограничены: k должен быть меньше числа разрядов типа. Для unsigned сдвиг влево определён по модулю 2^N, вправо — с заполнением нулями; сдвиг знакового отрицательного значения влево в C++17 — неопределённое поведение. Битовые операции не изменяют исходное число, если результат не присвоить.",
            "Проверка бита: (n >> k) & 1u. Установка: n | (1u << k). Сброс: n & ~(1u << k). Число единиц считайте циклом, пока n не станет нулём.", [
                code("bitcount", "Сигнальные биты", 'Ввод: целое n от 0 до 1000000. Прочитайте его в unsigned и выведите количество единичных битов двоичной записи. Используйте битовые операции: выделение младшего бита и сдвиг, а не деление с остатком.', 'unsigned n = 0;\nstd::cin >> n;\nint count = 0;\nwhile (n != 0) {\n    count += n & 1u;\n    n >>= 1;\n}\nstd::cout << count;', [("0", "0"), ("1", "1"), ("7", "3"), ("8", "1"), ("1023", "10"), ("1000000", "7")], ["Ненулевое число содержит хотя бы один единичный бит.", "Добавляйте n & 1u к счётчику, затем сдвигайте n вправо."], "Каждая итерация выделяет младший бит и сдвигает число; цикл завершается после прохода старшей единицы, поэтому число итераций равно позиции старшей единицы плюс один, а не количеству единиц.", difficulty=2),
                code("bitset", "Включённые датчики", 'Ввод: n (0…1000) и k (0…9). Установите бит номер k в n и выведите результат. Маску постройте сдвигом 1u << k.', 'unsigned n = 0;\nint k = 0;\nstd::cin >> n >> k;\nstd::cout << (n | (1u << k));', [("0 3", "8"), ("4 0", "5"), ("5 0", "5"), ("1000 0", "1001"), ("7 3", "15"), ("0 9", "512")], ["Если бит уже установлен, значение не изменится.", "1u << k — число с единственной единицей на позиции k."], "Операция | добавляет единичные биты, не трогая уже установленные.", difficulty=2),
                code("bitcheck", "Состояние флага", 'Ввод: n (0…1000) и k (0…9). Выведите 1, если бит номер k в n установлен, иначе 0.', 'unsigned n = 0;\nint k = 0;\nstd::cin >> n >> k;\nstd::cout << ((n >> k) & 1u);', [("5 0", "1"), ("5 1", "0"), ("1000 3", "1"), ("1000 0", "0"), ("1000 9", "1"), ("0 0", "0")], ["Сдвиньте интересующий бит на нулевую позицию.", "n & 1u выделяет младший бит результата."], "Проверка бита читает один разряд, не изменяя число.", headers="iostream"),
                choice("bitmask", "Что делает маска & ?", 'Что вернёт n & mask, если в mask единица только в одном разряде?', ["Все единичные биты числа n", "Значение mask, если в этом разряде у n единица, иначе 0", "Число n с установленным битом mask"], 1, ["& оставляет единицы только там, где единицы у обоих операндов.", "Маска из одного бита превращает & в проверку этого бита."], "Маска из одного бита возвращает либо сам этот бит (то есть mask), либо ноль. Тот же приём с маской из нескольких битов выделяет группу разрядов сразу."),
                choice("shiftsigned", "Сдвиг знакового отрицательного", 'Что говорит стандарт C++17 о (-1) << 3 для переменной int?', ["Результат равен −8 на всех платформах", "Неопределённое поведение", "Компилятор обязан выдать ошибку компиляции"], 1, ["Сдвиг влево отрицательного знакового значения в C++17 не определён.", "В C++20 правило изменилось: сдвиг определён как умножение по модулю 2^N."], "Поэтому битовые задачи читают вход в unsigned: опираться на знаковые сдвиги нельзя, а их правила зависят от версии стандарта.")
            ], ["биты", "маски", "unsigned"]),
        lesson("cmath", "Математика из <cmath>", "Считайте корни, модули и границы вещественных чисел.",
            "Заголовок <cmath> даёт std::sqrt(x) — квадратный корень, std::fabs(x) — модуль вещественного числа, std::floor(x) и std::ceil(x) — ближайшие целые снизу и сверху, std::pow(x, y) — степень. Все они возвращают double.\n\nРезультаты вещественных вычислений не обязаны быть точными: sqrt(2.0)*sqrt(2.0) может напечататься как 2.000000, но сравнивать double через == ненадёжно — сравнивайте разность с допуском. Для вывода фиксированного числа знаков используйте std::fixed << std::setprecision из <iomanip>. Для модуля целого int модуль — целочисленная операция: проверка знака или std::abs из <cstdlib>; std::fabs предназначен для вещественных типов.",
            program('std::cout << std::sqrt(2.0) << " " << std::fabs(-2.5);', "iostream cmath"),
            "sqrt отрицательного числа — доменная ошибка: результат NaN (или ошибка в зависимости от реализации). Задачи курса не подают отрицательные значения в sqrt. pow(0.0, 0.0) равен 1.0 по правилам IEEE, а точность pow зависит от реализации; для целых степеней надёжнее умножение в цикле.",
            "Корень — std::sqrt, модуль double — std::fabs, границы — std::floor и std::ceil. Сравнение double — только через разность и допуск.", [
                code("hypotenuse", "Гипотенуза рамы", 'Ввод: катеты a и b (0…1000, целые). Выведите длину гипотенузы с тремя знаками после точки, используя std::sqrt.', 'long long a = 0, b = 0;\nstd::cin >> a >> b;\nlong long sum = a * a + b * b;\nstd::cout << std::fixed << std::setprecision(3) << std::sqrt(static_cast<double>(sum));', [("3 4", "5.000"), ("0 0", "0.000"), ("1 1", "1.414"), ("6 8", "10.000"), ("5 12", "13.000"), ("0 7", "7.000")], ["Сначала вычислите сумму квадратов в long long, затем корень.", "Три знака задаёт setprecision(3) с fixed."], "Теорема Пифагора через <cmath>; сумма квадратов вычисляется в long long, поэтому не зависит от ширины int на конкретной платформе.", headers="iostream cmath iomanip", difficulty=2),
                code("bounds", "Границы полки", 'Ввод: длина заготовки double x (−100…100). Выведите floor(x) и ceil(x) через пробел как целые числа.', 'double x = 0;\nstd::cin >> x;\nstd::cout << static_cast<long long>(std::floor(x)) << " " << static_cast<long long>(std::ceil(x));', [("2.3", "2 3"), ("-2.3", "-3 -2"), ("5", "5 5"), ("-0.1", "-1 0"), ("7.9", "7 8"), ("0", "0 0")], ["floor движется вниз по числовой прямой, ceil — вверх.", "У целых значений floor и ceil совпадают."], "Разница проявляется только у нецелых значений, особенно у отрицательных.", headers="iostream cmath", difficulty=2),
                code("discarea", "Площадь диска", 'Ввод: радиус r (0…100). Выведите площадь круга с двумя знаками после точки, объявив const double pi = std::acos(-1.0);.', 'double r = 0;\nstd::cin >> r;\nconst double pi = std::acos(-1.0);\nstd::cout << std::fixed << std::setprecision(2) << pi * r * r;', [("1", "3.14"), ("2", "12.57"), ("0", "0.00"), ("10", "314.16"), ("0.5", "0.79"), ("7", "153.94")], ["acos(-1.0) даёт значение числа пи.", "Площадь — pi * r * r."], "Число пи не представимо в double точно; формула использует приближение, достаточное для двух знаков вывода.", headers="iostream cmath iomanip", difficulty=2),
                choice("intabs", "Модуль для int", 'Как корректно получить модуль целого int value?', ["std::fabs(value) — он подходит для любых типов", "Проверка знака с унарным минусом или std::abs из <cstdlib>", "Умножение на −1 без условий"], 1, ["fabs возвращает double и не предназначен для целочисленной логики.", "Унарный минус без проверки знака не даёт модуль."], "Модуль целого — целочисленная операция; вещественный fabs смешивает типы и не заменяет ветвление. Для INT_MIN унарный минус в int может переполниться, поэтому такие значения обрабатывают в более широком типе."),
                choice("dblsq", "Точность сравнения", 'Насколько надёжна проверка std::sqrt(2.0) * std::sqrt(2.0) == 2.0?', ["Гарантированно истинна по стандарту", "Не надёжна: результат double может отличаться от 2.0 на малую величину", "Истинна при включённом fixed"], 1, ["Вычисления с double выполняются с округлением.", "Равенство проверяют допуском: |x − 2.0| < eps."], "Корень из двух не представим точно; умножение может дать 2.0 или значение, отличающееся на один младший разряд.")
            ], ["cmath", "sqrt", "floor и ceil", "точность double"]),
        lesson("supplies", "Контрольная: планировщик запасов", "Проверьте формулы на границах и неожиданных случаях.",
            "Контрольная объединяет чтение, арифметику, упаковку и дробные результаты. До кода проверьте три случая: ничего не требуется, делится нацело, остаётся неполная группа. Для количества коробок при n ≥ 0 и k > 0 можно использовать (n + k - 1) / k, если сумма не переполняется. В наших задачах n + k - 1 ≤ 10100.\n\nЭта формула — округление вверх для неотрицательных целых, а не универсальное правило для любых знаков. Когда частное нужно как измерение, используйте вещественное деление, а не количество полных упаковок.",
            program('int n = 23, k = 6;\nstd::cout << (n + k - 1) / k;'),
            "Тест на n=0 важен: формула n/k+1 даст лишнюю коробку, когда остатка нет. Аналогично при n кратном k. Граничные тесты проверяют смысл формулы, а не только способность компилятора прочитать её.",
            "Различайте полные группы, все необходимые группы и вещественное отношение.", [
                code("containers", "Все контейнеры", 'Ввод: n образцов (0…10000) и вместимость k (1…100). Выведите минимальное число контейнеров, чтобы уложить все образцы.', 'int n = 0, k = 0;\nstd::cin >> n >> k;\nstd::cout << (n + k - 1) / k;', [("23 6", "4"), ("24 6", "4"), ("0 6", "0"), ("1 100", "1"), ("10000 99", "102"), ("99 99", "1"), ("100 99", "2")], ["Неполная последняя группа тоже требует контейнера.", "Прибавьте k-1 до деления на k."], "Добавка учитывает неполную группу, но не создаёт лишнюю при точном делении.", difficulty=2),
                output("unpack", "Разбор длительности", 'int seconds = 3671;\nstd::cout << seconds / 3600 << ":" << seconds / 60 % 60 << ":" << seconds % 60;', "1:1:11", ["В формате нет setfill и ведущих нулей.", "Минуты — остаток общего числа минут при делении на 60."], "Вывод именно 1:1:11, а не 01:01:11: форматирование не добавляется само."),
                code("reserve", "Запас после маршрута", 'Ввод: fuel (0…10000), участки a и b (0…100), число кругов n (0…50). Один километр требует одну единицу топлива; гарантируется fuel ≥ (a+b)*n. Выведите остаток.', 'int fuel = 0, a = 0, b = 0, n = 0;\nstd::cin >> fuel >> a >> b >> n;\nstd::cout << fuel - (a + b) * n;', [("100 3 7 4", "60"), ("0 0 0 0", "0"), ("10000 100 100 50", "0"), ("0 0 0 50", "0"), ("500 0 10 5", "450")], ["Один круг включает оба участка.", "Вычтите из fuel произведение длины круга и n."], "Гарантия достаточного топлива устраняет необходимость ветвления, но не меняет формулу.", difficulty=2),
                choice("boundary", "Самый полезный тест", 'Какая пара входов лучше всего обнаруживает ошибку формулы n/k+1 для числа всех необходимых коробок?', ["Только большие n", "n=0 и n, кратное k", "Только нечётные n при k=2"], 1, ["Лишняя единица ошибочна именно при отсутствии остатка.", "Проверьте пустую поставку и полностью заполненные коробки."], "Тестировать нужно смысловую границу между полной и неполной последней группой."),
                code("report", "Отчёт снабжения", 'Ввод: n пайков (0…10000), k пайков в коробке (1…100), crew (1…100). Выведите две строки: Boxes: <всего коробок> и Per person: <n/crew с 2 знаками>.', 'int n = 0, k = 0, crew = 0;\nstd::cin >> n >> k >> crew;\nstd::cout << "Boxes: " << (n + k - 1) / k << "\\nPer person: "\n          << std::fixed << std::setprecision(2) << static_cast<double>(n) / crew;', [("23 6 4", "Boxes: 4\nPer person: 5.75"), ("0 3 2", "Boxes: 0\nPer person: 0.00"), ("10000 100 100", "Boxes: 100\nPer person: 100.00"), ("1 100 3", "Boxes: 1\nPer person: 0.33"), ("100 99 7", "Boxes: 2\nPer person: 14.29")], ["Коробки и доля на человека требуют разных видов деления.", "Для доли приведите n к double до деления; для коробок используйте округление вверх."], "Это две интерпретации одних данных: дискретная упаковка и вещественная доля.", headers="iostream iomanip", difficulty=3)
            ], ["контрольная", "деление", "граничные случаи"])
    ])]
